<template><div class="page"><div class="page-header"><h2>保养工单</h2></div><el-card shadow="never"><el-table :data="items" v-loading="loading" stripe size="small" highlight-current-row @row-click="open"><el-table-column prop="daily_maintenance_id" label="保养单号" width="110"/><el-table-column label="门店" width="90"><template #default="{row}">{{ row.store_cust_card || custCard(row.store_id) }}</template></el-table-column><el-table-column prop="short_description" label="简述" min-width="140" show-overflow-tooltip/><el-table-column label="状态" width="80"><template #default="{row}"><el-tag :type="statusTag(row.current_status)" size="small">{{ statusLabel(row.current_status) }}</el-tag></template></el-table-column><el-table-column label="工程师" width="80"><template #default="{row}">{{ userName(row.firstor) }}</template></el-table-column><el-table-column label="请求时间" width="110"><template #default="{row}">{{ row.request_time||'-' }}</template></el-table-column><el-table-column label="关单时间" width="110"><template #default="{row}">{{ row.close_time||'-' }}</template></el-table-column></el-table><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card><el-dialog :title="'保养工单 — '+(detail?.daily_maintenance_id||'')" v-model="drawer" width="550px"><template v-if="detail"><el-descriptions :column="2" border size="small"><el-descriptions-item label="保养单号">{{ detail.daily_maintenance_id }}</el-descriptions-item><el-descriptions-item label="门店">{{ detail.store_cust_card || custCard(detail.store_id) }}</el-descriptions-item><el-descriptions-item label="简述" :span="2">{{ detail.short_description||'-' }}</el-descriptions-item><el-descriptions-item label="状态">{{ statusLabel(detail.current_status) }}</el-descriptions-item><el-descriptions-item label="工程师">{{ userName(detail.firstor) }}</el-descriptions-item><el-descriptions-item label="请求时间">{{ detail.request_time||'-' }}</el-descriptions-item><el-descriptions-item label="关单时间">{{ detail.close_time||'-' }}</el-descriptions-item><el-descriptions-item label="详细描述" :span="2">{{ detail.detail_description||'-' }}</el-descriptions-item></el-descriptions></template></el-dialog></div></template>
<script setup lang="ts">import AppPagination from '@/components/common/AppPagination.vue';import {useListPage} from '@/composables/useListPage';import {useDetailDrawer} from '@/composables/useDetailDrawer';import {useUserNames} from '@/composables/useUserNames';import {useCustomerCards} from '@/composables/useCustomerCards';import {fetchMaintenanceT17} from '@/api/itsm';import type {MntRecord} from '@/api/itsm'
const{items,loading,page,perPage,total}=useListPage<MntRecord>(fetchMaintenanceT17);const{drawer,detail,open}=useDetailDrawer<MntRecord>();const{userName}=useUserNames();const{custCard}=useCustomerCards()
function statusTag(s:string){const m:Record<string,string>={'1':'info','2':'primary','3':'success','4':'warning','5':'primary','9':'danger'};return m[s]||'info'}
function statusLabel(s:string){const m:Record<string,string>={'1':'新建','2':'分配','3':'关闭','4':'未解决','5':'已解决','9':'作废'};return m[s]||s}</script>
